class Solution {
public:
    bool canConvert(string str1, string str2) {
        if (str1 == str2) {
            return true;
        }
        vector<int> mapping(26, -1);
        set<char> targets;
        for (int i = 0; i < static_cast<int>(str1.size()); ++i) {
            int c = str1[i] - 'a';
            int d = str2[i] - 'a';
            if (mapping[c] != -1 && mapping[c] != d) {
                return false;
            }
            mapping[c] = d;
            targets.insert(str2[i]);
        }
        return targets.size() < 26;
    }
};
